/**
 * Dummy festival data.
 *
 * There is no backend, so this module *is* the database. Dates are generated
 * relative to "today" at import time (see `isoDate`) so the demo always has a
 * realistic list of upcoming festivals instead of dates that silently rot.
 *
 * Shapes:
 *   festival.lineup[] -> { name, genre, stage, day, start, end, bio }
 *       `day` is 1-based (day 1 = festival.startDate)
 *       `start`/`end` are 24h "HH:MM" strings
 *       `genre` is unused: nothing displays it and the search matches artist
 *       names only. It stays on the records in case it is wanted again.
 *   festival.pois[]   -> { id, name, type, x, y, note }
 *       `x`/`y` are percentages (0-100) positioning the pin on the grounds map
 */

const pad = (n) => String(n).padStart(2, '0')

/** "YYYY-MM-DD" for local midnight `offset` days from today. */
function isoDate(offset) {
  const d = new Date()
  d.setHours(0, 0, 0, 0)
  d.setDate(d.getDate() + offset)
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`
}

/** Last day of a festival that runs `days` days starting at `startOffset`. */
const festivalDates = (startOffset, days) => ({
  startDate: isoDate(startOffset),
  endDate: isoDate(startOffset + days - 1),
  days,
})

