export default FESTIVALS

/** Look up one festival by its route id. Returns undefined if not found. */
export function getFestival(id) {
  return FESTIVALS.find((f) => f.id === id)
}

/** Every distinct artist name across every festival, alphabetized. */
export function allArtistNames() {
  const names = new Set()
  FESTIVALS.forEach((f) => f.lineup.forEach((a) => names.add(a.name)))
  return [...names].sort((a, b) => a.localeCompare(b))
}
